<?php
namespace Ishep\Services;use RuntimeException;
final class PrivateDocumentStorage
{public function __construct(private array $config){}public function store(array $validated,bool $http=true):array{$date=gmdate('Y/m');$dir=$this->config['root'].'/'.$date;if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))throw new RuntimeException('Private storage is unavailable.');$key=bin2hex(random_bytes(24)).'.'.$validated['extension'];$relative=$date.'/'.$key;$target=$dir.'/'.$key;$ok=$http?move_uploaded_file($validated['tmp'],$target):copy($validated['tmp'],$target);if(!$ok)throw new RuntimeException('The file could not be stored safely.');@chmod($target,0600);return['storage_key'=>$key,'relative_path'=>$relative];}public function path(string $relative):string{$root=realpath($this->config['root']);if($root===false||str_contains($relative,'..')||str_starts_with($relative,'/')||preg_match('/^[A-Za-z]:/',$relative))throw new RuntimeException('Document file unavailable.');$path=realpath($root.'/'.str_replace('\\','/',$relative));if($path===false||!is_file($path)||!str_starts_with($path,$root.DIRECTORY_SEPARATOR))throw new RuntimeException('Document file unavailable.');return$path;}public function remove(string $relative):bool{try{$path=$this->path($relative);return unlink($path);}catch(RuntimeException){return false;}}public function config():array{return$this->config;}}
